   265  void IiqDecoder::CorrectPhaseOneC(ByteStream meta_data, uint32 split_row,
   266                                    uint32 split_col) {
   267    meta_data.skipBytes(8);
   268    const uint32 bytes_to_entries = meta_data.getU32();
   269    meta_data.setPosition(bytes_to_entries);
   270    const uint32 entries_count = meta_data.getU32();
   271    meta_data.skipBytes(4);
   272
   273    // this is how much is to be read for all the entries
   274    ByteStream entries(meta_data.getStream(entries_count, 12));
   275    meta_data.setPosition(0);
   276
   277    for (uint32 entry = 0; entry < entries_count; entry++) {
   278      const uint32 tag = entries.getU32();
   279      const uint32 len = entries.getU32();
   280      const uint32 offset = entries.getU32();
   281
   282      switch (tag) {
   283      case 0x431:
   284        if (!iiq.quadrantMultipliers)
   285          return;
   286
   287        CorrectQuadrantMultipliersCombined(meta_data.getSubStream(offset, len),
   288                                           split_row, split_col);
   289        return;
   290      default:
   291        break;
   292      }
   293    }
   294  }
